import org.apache.nifi.processor.io.StreamCallback
import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.nio.charset.StandardCharsets
import java.time.LocalDate
import java.time.LocalDateTime
import java.time.OffsetDateTime
import java.time.ZonedDateTime
import java.time.format.DateTimeFormatter
import java.time.format.DateTimeParseException

def flowFile = session.get()
if (!flowFile) return

try {
    def transformationsAttr = flowFile.getAttribute("transformations.json")

    def hasText = { val -> val != null && !val.trim().isEmpty() }

    if (!hasText(transformationsAttr)) {
        flowFile = session.putAttribute(flowFile, "transformations.applied", "false")
        flowFile = session.putAttribute(flowFile, "transformations.reason", "No transformations.json attribute found")
        session.transfer(flowFile, REL_SUCCESS)
        return
    }

    def parsedTransformations = new JsonSlurper().parseText(transformationsAttr)
    def transformations = parsedTransformations?.columns ?: parsedTransformations

    if (!(transformations instanceof Map) || transformations.isEmpty()) {
        flowFile = session.putAttribute(flowFile, "transformations.applied", "false")
        flowFile = session.putAttribute(flowFile, "transformations.reason", "No transformation rules found")
        session.transfer(flowFile, REL_SUCCESS)
        return
    }

    def parseDateValue = { value, columnName ->
        if (value == null) return null
        def text = value.toString().trim()
        if (!text) return text

        def datePatterns = [
            DateTimeFormatter.ISO_LOCAL_DATE,                 // 2026-01-01
            DateTimeFormatter.ofPattern("dd/MM/yyyy"),       // 01/01/2026
            DateTimeFormatter.ofPattern("dd-MM-yyyy"),       // 01-01-2026
            DateTimeFormatter.ofPattern("yyyy/MM/dd"),       // 2026/01/01
            DateTimeFormatter.ofPattern("dd/MM/yy"),         // 01/01/26
            DateTimeFormatter.ofPattern("dd-MM-yy")          // 01-01-26
        ]

        for (formatter in datePatterns) {
            try {
                return LocalDate.parse(text, formatter).format(DateTimeFormatter.ISO_LOCAL_DATE)
            } catch (DateTimeParseException ignored) {}
        }

        throw new IllegalStateException("Date conversion failed for column '${columnName}' with value '${value}'")
    }

    def parseTimestampValue = { value, columnName ->
        if (value == null) return null
        def text = value.toString().trim()
        if (!text) return text

        // 1) Intentar formatos ISO con zona
        try {
            return OffsetDateTime.parse(text).toLocalDateTime().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME)
        } catch (DateTimeParseException ignored) {}

        try {
            return ZonedDateTime.parse(text).toLocalDateTime().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME)
        } catch (DateTimeParseException ignored) {}

        // 2) Intentar formatos ISO locales
        try {
            return LocalDateTime.parse(text, DateTimeFormatter.ISO_LOCAL_DATE_TIME)
                    .format(DateTimeFormatter.ISO_LOCAL_DATE_TIME)
        } catch (DateTimeParseException ignored) {}

        // 3) Intentar patrones comunes
        def timestampPatterns = [
            DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"),
            DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm"),
            DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm:ss"),
            DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm"),
            DateTimeFormatter.ofPattern("dd-MM-yyyy HH:mm:ss"),
            DateTimeFormatter.ofPattern("dd-MM-yyyy HH:mm"),
            DateTimeFormatter.ofPattern("yyyy/MM/dd HH:mm:ss"),
            DateTimeFormatter.ofPattern("yyyy/MM/dd HH:mm"),
            DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss"),
            DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm")
        ]

        for (formatter in timestampPatterns) {
            try {
                return LocalDateTime.parse(text, formatter).format(DateTimeFormatter.ISO_LOCAL_DATE_TIME)
            } catch (DateTimeParseException ignored) {}
        }

        // 4) Si viene solo fecha, convertirla a medianoche
        try {
            def d = LocalDate.parse(text, DateTimeFormatter.ISO_LOCAL_DATE)
            return d.atStartOfDay().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME)
        } catch (DateTimeParseException ignored) {}

        throw new IllegalStateException("Timestamp conversion failed for column '${columnName}' with value '${value}'")
    }

    def castValue = { value, targetType, columnName ->
        if (value == null || targetType == null) return value

        try {
            switch (targetType.toString().toLowerCase()) {
                case "int":
                case "integer":
                    return Integer.parseInt(value.toString())
                case "long":
                    return Long.parseLong(value.toString())
                case "double":
                case "decimal":
                    return Double.parseDouble(value.toString())
                case "float":
                    return Float.parseFloat(value.toString())
                case "boolean":
                    return Boolean.parseBoolean(value.toString())
                case "string":
                    return value.toString()
                case "timestamp":
                    return parseTimestampValue(value, columnName)
                case "date":
                    return parseDateValue(value, columnName)
                default:
                    return value
            }
        } catch (Exception ex) {
            throw new IllegalStateException("Type conversion failed for column '${columnName}' with value '${value}' to type '${targetType}'", ex)
        }
    }

    def normalizeCase = { value, caseType ->
        if (!(value instanceof String) || caseType == null) return value

        switch (caseType.toString().toLowerCase()) {
            case "upper":
            case "uppercase":
                return value.toUpperCase()
            case "lower":
            case "lowercase":
                return value.toLowerCase()
            default:
                return value
        }
    }

    def applyRulesToRow = { row ->
        if (!(row instanceof Map)) return

        transformations.each { originalColumn, rules ->
            if (!(rules instanceof Map)) return

            def columnName = originalColumn.toString()

            if (!row.containsKey(columnName)) return

            def currentValue = row[columnName]

            // 1. nullDefault
            if (rules.containsKey("nullDefault") && currentValue == null) {
                currentValue = rules["nullDefault"]
            }

            // 2. trim
            if (rules.containsKey("trim") &&
                rules["trim"] == true &&
                currentValue instanceof String) {
                currentValue = currentValue.trim()
            }

            // 3. case
            if (rules.containsKey("case")) {
                currentValue = normalizeCase(currentValue, rules["case"])
            }

            // 4. type
            if (rules.containsKey("type") && currentValue != null) {
                currentValue = castValue(currentValue, rules["type"], columnName)
            }

            // Actualizar valor antes de rename
            row[columnName] = currentValue

            // 5. rename
            if (rules.containsKey("rename")) {
                def newColumnName = rules["rename"]?.toString()

                if (newColumnName != null && !newColumnName.trim().isEmpty() && newColumnName != columnName) {
                    row[newColumnName] = row[columnName]
                    row.remove(columnName)
                }
            }
        }
    }

    flowFile = session.write(flowFile, { inputStream, outputStream ->
        def text = inputStream.getText(StandardCharsets.UTF_8.name())

        if (!hasText(text)) {
            throw new IllegalStateException("FlowFile content is empty")
        }

        def json = new JsonSlurper().parseText(text)

        if (json instanceof List) {
            json.each { applyRulesToRow(it) }
        } else if (json instanceof Map) {
            applyRulesToRow(json)
        } else {
            throw new IllegalStateException("Unsupported JSON content structure. Expected List or Map.")
        }

        outputStream.write(JsonOutput.toJson(json).getBytes(StandardCharsets.UTF_8))
    } as StreamCallback)

    flowFile = session.putAttribute(flowFile, "transformations.applied", "true")
    flowFile = session.putAttribute(flowFile, "transformations.reason", "Transformation rules applied successfully")
    session.transfer(flowFile, REL_SUCCESS)

} catch (Exception e) {
    log.error("Error applying transformations", e)
    flowFile = session.putAttribute(flowFile, "transformations.applied", "false")
    flowFile = session.putAttribute(flowFile, "transformations.error", e.getMessage() ?: "unknown error")
    session.transfer(flowFile, REL_FAILURE)
}

